const firstPage={en:'Preview of the first page',ru:'Предпросмотр первой страницы',zh:'第一页预览',es:'Vista previa de la primera página',fr:'Aperçu de la première page',de:'Vorschau der ersten Seite',pt:'Prévia da primeira página',it:'Anteprima della prima pagina',tr:'İlk sayfanın önizlemesi',ja:'最初のページのプレビュー',ko:'첫 페이지 미리 보기',ar:'معاينة الصفحة الأولى',hi:'पहले पेज का पूर्वावलोकन'};
for(const [code,text]of Object.entries(previewTranslations))text.previewFirstPage=firstPage[code];
